cd /private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/9d0ee1f5-45bd-44d3-902c-2c8ed607caa9; cat > tests/zz-tmp.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { listNotifications, markAllRead } from "@/server/services/notification-service";
import { emit } from "@/lib/event-bus";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("flows", async () => {
  const t = await createTenant("tmpx", "free");
  const list = (who: "owner"|"admin"|"member"|"viewer") => listNotifications(t.actors[who], { orgId: t.org.id, recipientId: t.userIds[who], unreadOnly: false, limit: 50, cursor: null });
  const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.admin }));
  await issueService.moveIssue(t.actors.member, { orgId: t.org.id, issueId: issue.id, toStatus: "done", toIndex: 0 } as never);
  console.log((await list("admin")).items.map(n => [n.kind, n.href]));
  await emit("member.joined", { orgId: t.org.id, actorId: t.userIds.viewer, occurredAt: issue.createdAt, memberId: "m" as never, userId: t.userIds.viewer, role: "viewer" });
  for (let i = 0; i < 6; i++) { try { await projectService.createProject(t.actors.owner, { orgId: t.org.id, name: "P" + i } as never); } catch (e) { console.log("refused", (e as Error).message); } }
  console.log((await list("owner")).items.map(n => [n.kind, n.href, n.title]));
  console.log((await list("viewer")).items.length);
  await markAllRead(t.actors.owner, t.org.id);
  console.log((await list("admin")).items.map(n => n.readAt));
});
EOF
npx vitest run tests/zz-tmp.test.ts 2>&1 | grep -v "^npm warn" | head -60; rm tests/zz-tmp.test.ts

